Go:  Go’s method of constructing a mutable object looks like this:

```go
type MutableMap struct {
    keyvals map[string]*keyValue
}

type keyValue struct {
  val string
  src *KeyValuePair
}
func NewKeyValue(v KVPair, src KVPair) KeyValue {
  if v == nil {
    panic("NewKeyValue: nil src")
  }
  if src == nil {
    panic("NewKeyValue: nil key")
  }
  kv := &keyValue{v: v, src: src}
  if len(kv.src) == 0 && len(&kv.src.val) > 0 {
    panic("NewKeyValue: key with key and value")
  }
  kv.src.val = kv.src.val[0]
  return kv
}

func Copy(src MutableMap) MutableMap {
  dst := make(MutableMap, len(src))
  dst.p = make(KeyValue, len(src))
  for k, v := range src.keyvals {
    dst.p[k] = copyKeyValue(v)
  }
  return dst
}

func CopyFrom(src MutableMap) MutableMap {
  dst := make(MutableMap, len(src.keyvals))
  dst.p = copyKeyValueMap(src.keyvals)
  for _, v := range src.keyvals {
    dst.p[v.src.key] = v;
  }
  return dst
}
```

